import numpy as np, sys
f=sys.argv[1]
L=open(f).read().split("\n")[2:]
at=[(l.split()[0], np.array(list(map(float,l.split()[1:4])))) for l in L if l.strip()]
os_=1; nb=[0,2,3,7,11,19]
def ang(i,j,k):
    a=at[i][1]-at[j][1]; b=at[k][1]-at[j][1]
    return np.degrees(np.arccos(np.dot(a,b)/np.linalg.norm(a)/np.linalg.norm(b)))
for i in nb: print(i, at[i][0], round(np.linalg.norm(at[i][1]-at[os_][1]),3))
for a in range(len(nb)):
    for b in range(a+1,len(nb)):
        print(nb[a],nb[b], round(ang(nb[a],os_,nb[b]),1))
EOF
